/**
 * Agent setup.
 *
 * Creates a Pi Agent configured for in-browser web development.
 * Registers common provider APIs at startup so any model works.
 * The agent uses five browser tools (read, write, get_screenshot,
 * get_console, reload) instead of the built-in filesystem tools.
 */

import { Agent } from "@earendil-works/pi-agent-core/base";
import { getModel } from "@earendil-works/pi-ai/base";
import { register as registerOpenAICompletions } from "@earendil-works/pi-ai/openai-completions";

import { browserTools } from "./browser-tools";
import { getSettings, parseModelString } from "./settings";

const SYSTEM_PROMPT = `You are a web developer running entirely in the browser.
You have tools to edit, read, fetch, and verify a single self-contained HTML page.

- edit(description, oldText, newText): Modify the page. Pass empty oldText to APPEND newText to the end of the page. Pass non-empty oldText to replace an exact chunk. Always include a short description of what you're adding.
- read(): Read the current HTML content.
- fetch(url): GET a URL for research (info, data, placeholder images). CORS may block some sites.
- get_screenshot(): Capture the rendered page to visually verify your work.
- get_console(): Read browser console output and errors.
- reload(): Force-reload the preview.

The preview panel renders your HTML in real time as you edit.
Be concise in your explanations — let the code speak.

BUILD INCREMENTALLY. Do not write the whole page at once. Start from an empty
file and append the page section by section with separate edit() calls — for
example: (1) document skeleton + <head> + base styles, (2) header/nav,
(3) hero section, (4) features/menu, (5) footer. Append by passing empty
oldText. Each append streams live into the preview, so build top-to-bottom.

KEEP IT VISIBLE WHILE STREAMING. The preview updates token-by-token as you
write, so the page must be readable at every intermediate step:
- Your VERY FIRST edit must establish readable colors: open the document
  skeleton and put a <style> with the body background-color and color at the
  top, BEFORE any visible text. Do not add text content until colors are set.
- Never add light-colored text before its background is in place. If you add
  a dark background first, light text stays readable as it streams.
- Make sure every section has readable contrast the moment it appears.
  Check: would the latest streamed chunk be legible on the background so far?

Use modern CSS (flexbox/grid, custom properties) and clean JavaScript.
Keep every HTML document well-formed; close the tags you open so partial
renders stay valid. After the page is complete, use get_screenshot() to
verify and fix any issues with targeted replacements.

JAVASCRIPT COMES LAST. The preview re-renders live as you stream, and scripts
run during streaming can hide content (scroll-reveal observers, opacity
transitions, animation triggers) before the page is ready — leaving sections
invisible. So:
- Build ALL static HTML and CSS first, with everything visible by default.
- Do not write any <script> until the page is structurally complete.
- Add JavaScript (interactivity, animations, scroll effects) in a final edit
  at the very end, and make sure it never hides content that is visible by
default in the static markup.
This keeps the page readable at every step of the stream.`;

/** Register common provider APIs so models from any provider work. */
export function registerProviders(): void {
	registerOpenAICompletions();
	// anthropic-messages would be: import { register } from "@earendil-works/pi-ai/anthropic"; register();
}

/** Create the browser agent with current settings. */
export function createBrowserAgent(): Agent {
	const settings = getSettings();
	const { provider, model: modelId } = parseModelString(settings.model);

	const model = getModel(provider as never, modelId as never);
	if (!model) {
		throw new Error(`Model not found: ${settings.model}. Make sure the provider/model string is correct.`);
	}

	const agent = new Agent({
		initialState: {
			systemPrompt: SYSTEM_PROMPT,
			model,
			thinkingLevel: "off",
			tools: browserTools,
		},
		getApiKey: async () => {
			const current = getSettings();
			return current.apiKey || undefined;
		},
	});

	return agent;
}
/**
 * Browser tools for the agent.
 *
 * Five tools that operate on the single in-memory file and the preview iframe:
 * - read:           Read the current HTML content
 * - edit:           Append to or replace parts of the page (chunked building)
 * - get_screenshot: Capture the rendered preview as base64 image
 * - get_console:    Read browser console output
 * - reload:         Force-reload the preview
 */

import type { AgentTool } from "@earendil-works/pi-agent-core/base";
import { Type } from "@earendil-works/pi-ai/base";

import { getFile, setFile } from "./file";
import { getScreenshot, getConsole, reload as reloadPreview } from "./preview";

/** Read the current HTML content of the single file. */
const readTool: AgentTool = {
	name: "read",
	label: "Read",
	description: "Read the current HTML content of the page.",
	parameters: Type.Object({}),
	execute: async () => {
		const content = getFile();
		return {
			content: [{ type: "text", text: content || "(file is empty)" }],
			details: { length: content.length },
		};
	},
};

/**
 * Edit the page: replace `oldText` with `newText`.
 * Pass an empty `oldText` to append `newText` to the end of the file.
 * Use `description` to narrate what this edit adds.
 */
const editTool: AgentTool = {
	name: "edit",
	label: "Edit",
	description:
		"Edit the HTML page by replacing a chunk. Pass empty oldText to append. Always describe what you're adding.",
	parameters: Type.Object({
		description: Type.String({
			description: "A short description of what this edit does, e.g. 'Adding the hero section'.",
		}),
		oldText: Type.String({
			description: "The exact text to replace. Use an empty string to append to the end of the file.",
		}),
		newText: Type.String({
			description: "The replacement text (or the new chunk to append if oldText is empty).",
		}),
	}),
	execute: async (_id, params) => {
		const { description, oldText, newText } = params as {
			description: string;
			oldText: string;
			newText: string;
		};

		const current = getFile();

		// Append mode: empty oldText adds newText to the end.
		if (oldText === "") {
			setFile(current + newText);
			return {
				content: [{ type: "text", text: `Appended ${newText.length} bytes. ${description}` }],
				details: { mode: "append", bytes: newText.length, description },
			};
		}

		// Replace mode: swap the first occurrence of oldText for newText.
		if (!current.includes(oldText)) {
			throw new Error(`oldText not found in the file. Make sure it matches the current content exactly.`);
		}

		setFile(current.replace(oldText, newText));
		return {
			content: [{ type: "text", text: `Replaced ${oldText.length} bytes with ${newText.length} bytes. ${description}` }],
			details: { mode: "replace", description },
		};
	},
};

/** Capture the rendered preview as a base64-encoded image (SVG screenshot). */
const getScreenshotTool: AgentTool = {
	name: "get_screenshot",
	label: "Screenshot",
	description: "Capture the rendered preview page as a base64-encoded SVG image to visually verify your work.",
	parameters: Type.Object({}),
	execute: async () => {
		const screenshot = await getScreenshot();
		// Return as image content if it looks like base64, otherwise as text error
		if (screenshot.startsWith("PHN2Zz") || screenshot.startsWith("<svg")) {
			const data = screenshot.startsWith("<svg")
				? btoa(unescape(encodeURIComponent(screenshot)))
				: screenshot;
			return {
				content: [{ type: "image", data, mimeType: "image/svg+xml" }],
				details: { format: "svg", size: data.length },
			};
		}
		return {
			content: [{ type: "text", text: screenshot }],
			details: { error: true },
		};
	},
};

/** Read captured browser console output from the preview. */
const getConsoleTool: AgentTool = {
	name: "get_console",
	label: "Console",
	description: "Read browser console output and errors from the preview page. Useful for debugging JavaScript.",
	parameters: Type.Object({}),
	execute: async () => {
		const output = getConsole();
		return {
			content: [{ type: "text", text: output }],
			details: {},
		};
	},
};

/** Force-reload the preview iframe. */
const reloadTool: AgentTool = {
	name: "reload",
	label: "Reload",
	description: "Force-reload the preview page. Clears the console and re-renders the current HTML.",
	parameters: Type.Object({}),
	execute: async () => {
		reloadPreview();
		return {
			content: [{ type: "text", text: "Preview reloaded." }],
			details: {},
		};
	},
};

/** Fetch content from a URL (HTTP GET) for research. Subject to CORS. */
const fetchTool: AgentTool = {
	name: "fetch",
	label: "Fetch",
	description:
		"Fetch text content from a URL via HTTP GET. Use for research, looking up information, or fetching resources (e.g. placeholder image URLs, API data). Subject to browser CORS — some sites block cross-origin requests.",
	parameters: Type.Object({
		url: Type.String({ description: "The http(s) URL to fetch." }),
	}),
	execute: async (_id, params) => {
		const { url } = params as { url: string };
		const res = await fetch(url);
		const text = await res.text();
		const truncated =
			text.length > 8000
				? text.slice(0, 8000) + `\n...(truncated, ${text.length} bytes total)`
				: text;
		return {
			content: [{ type: "text", text: `HTTP ${res.status} ${res.statusText}\n\n${truncated}` }],
			details: { status: res.status, url, length: text.length },
		};
	},
};

/** All browser tools, ready to be passed to the Agent. */
export const browserTools: AgentTool[] = [
	readTool,
	editTool,
	getScreenshotTool,
	getConsoleTool,
	reloadTool,
	fetchTool,
];
/**
 * Chat UI.
 *
 * Subscribes to agent events and renders them to the DOM.
 * - Assistant text is rendered as markdown.
 * - Edit tool calls show their description and stream the live preview.
 * - During execution only the LATEST tool call / message is shown normally;
 *   everything earlier collapses into a "N previous steps" disclosure whose
 *   text is dimmed and italicized.
 */

import type { Agent } from "@earendil-works/pi-agent-core/base";
import type { AgentEvent } from "@earendil-works/pi-agent-core/base";
import { marked } from "marked";

import { getFile } from "./file";
import { renderPartial } from "./preview";

const messagesEl = document.getElementById("messages") as HTMLDivElement;
const inputEl = document.getElementById("chat-input") as HTMLTextAreaElement;
const sendBtn = document.getElementById("send-btn") as HTMLButtonElement;

marked.setOptions({ breaks: true, gfm: true });

// --- Markdown + sanitize --------------------------------------------------

function renderMarkdown(md: string): string {
	const raw = marked.parse(md, { async: false }) as string;
	return sanitizeHtml(raw);
}

function sanitizeHtml(html: string): string {
	const doc = new DOMParser().parseFromString(html, "text/html");
	doc.querySelectorAll("script").forEach((el) => el.remove());
	doc.querySelectorAll("*").forEach((el) => {
		for (const attr of Array.from(el.attributes)) {
			if (attr.name.startsWith("on")) el.removeAttribute(attr.name);
			else if (attr.name === "href" || attr.name === "src") {
				if (attr.value.trim().toLowerCase().startsWith("javascript:")) el.removeAttribute(attr.name);
			}
		}
	});
	return doc.body.innerHTML;
}

function escapeHtml(text: string): string {
	const div = document.createElement("div");
	div.textContent = text;
	return div.innerHTML;
}

// --- Collapsible history --------------------------------------------------
//
// historyEl holds every assistant text / tool-call element except the most
// recent one (currentEl). Only currentEl is rendered with full styling; items
// inside historyEl get the dimmed, italic "history" treatment.

let historyEl: HTMLDetailsElement | null = null;
let currentEl: HTMLElement | null = null;

/** Move currentEl into the collapsible history, then clear it. */
function parkCurrent(): void {
	if (!currentEl) return;

	if (!historyEl) {
		historyEl = document.createElement("details");
		historyEl.className = "history";
		const summary = document.createElement("summary");
		historyEl.appendChild(summary);
		messagesEl.appendChild(historyEl);
	}

	currentEl.classList.add("history-item");
	historyEl.appendChild(currentEl);
	currentEl = null;
	updateHistorySummary();
}

/** Park whatever is current, then promote `el` as the new current element. */
function makeCurrent(el: HTMLElement): void {
	if (currentEl === el) return;
	parkCurrent();
	messagesEl.appendChild(el);
	currentEl = el;
	scrollToBottom();
}

function updateHistorySummary(): void {
	if (!historyEl) return;
	const count = historyEl.querySelectorAll(".history-item").length;
	const summary = historyEl.querySelector("summary");
	if (summary) summary.textContent = `${count} previous step${count === 1 ? "" : "s"}`;
	historyEl.style.display = count > 0 ? "" : "none";
}

// --- Message + tool-call element factories --------------------------------

function createMessageEl(role: "user" | "assistant", content = ""): HTMLDivElement {
	const el = document.createElement("div");
	el.className = `message ${role}`;
	if (role === "assistant") el.innerHTML = renderMarkdown(content);
	else el.textContent = content;
	return el;
}

// --- Thinking indicator ---------------------------------------------------

let thinkingEl: HTMLDivElement | null = null;

function showThinking(): void {
	if (thinkingEl) return;
	thinkingEl = document.createElement("div");
	thinkingEl.className = "thinking";
	thinkingEl.innerHTML = `<span class="think-dot"></span> thinking…`;
	messagesEl.appendChild(thinkingEl);
	scrollToBottom();
}

function hideThinking(): void {
	if (thinkingEl) {
		thinkingEl.remove();
		thinkingEl = null;
	}
}

// --- Tool-call indicators -------------------------------------------------

const toolCallEls = new Map<string, HTMLDivElement>();

function ensureToolCallEl(toolCallId: string, toolName: string, description: string): HTMLDivElement {
	const existing = toolCallEls.get(toolCallId);
	if (existing) {
		updateToolCallEl(existing, toolName, description);
		return existing;
	}

	const el = document.createElement("div");
	el.className = "tool-call running";
	updateToolCallEl(el, toolName, description);
	toolCallEls.set(toolCallId, el);
	makeCurrent(el);
	return el;
}

function updateToolCallEl(el: HTMLDivElement, toolName: string, description: string): void {
	const verb = toolName === "edit" ? "editing" : toolName.replace(/_/g, " ");
	el.innerHTML =
		`<span class="tool-icon">⚙</span> ` +
		`<span class="tool-body"><span class="tool-name">${escapeHtml(verb)}</span>` +
		(description ? `<span class="tool-desc">${escapeHtml(description)}</span>` : "") +
		`</span>` +
		`<span class="tool-status">running…</span>`;
}

function markToolCallDone(el: HTMLDivElement): void {
	el.classList.remove("running");
	const status = el.querySelector(".tool-status");
	if (status) status.textContent = "done";
}

function scrollToBottom(): void {
	messagesEl.scrollTop = messagesEl.scrollHeight;
}

// --- Streaming state ------------------------------------------------------

let currentAssistantEl: HTMLDivElement | null = null;

// --- Init -----------------------------------------------------------------

export function initChatUI(agent: Agent): void {
	agent.subscribe((event: AgentEvent) => handleAgentEvent(event));

	sendBtn.addEventListener("click", () => void sendMessage(agent));

	inputEl.addEventListener("keydown", (e) => {
		if (e.key === "Enter" && !e.shiftKey) {
			e.preventDefault();
			void sendMessage(agent);
		}
	});

	inputEl.addEventListener("input", () => {
		inputEl.style.height = "auto";
		inputEl.style.height = `${Math.min(inputEl.scrollHeight, 120)}px`;
	});
}

async function sendMessage(agent: Agent): Promise<void> {
	const text = inputEl.value.trim();
	if (!text) return;

	inputEl.value = "";
	inputEl.style.height = "auto";
	sendBtn.disabled = true;

	const userEl = createMessageEl("user", text);
	messagesEl.appendChild(userEl);
	scrollToBottom();

	try {
		await agent.prompt(text);
	} catch (e) {
		const errorEl = createMessageEl("assistant", `**Error:** ${(e as Error).message}`);
		makeCurrent(errorEl);
	} finally {
		sendBtn.disabled = false;
		inputEl.focus();
	}
}

function handleAgentEvent(event: AgentEvent): void {
	switch (event.type) {
		case "agent_start":
		case "turn_start":
			showThinking();
			break;

		case "agent_end":
			hideThinking();
			break;

		case "message_start": {
			if (event.message.role === "assistant") {
				hideThinking();
				// Bubble is created lazily on the first text delta, so a tool-call-only
				// message never produces an empty bubble.
			}
			break;
		}

		case "message_update": {
			const { assistantMessageEvent } = event;

			if (assistantMessageEvent.type === "text_delta") {
				const text = getText(event.message);
				if (text) {
					if (!currentAssistantEl) {
						currentAssistantEl = createMessageEl("assistant", "");
						messagesEl.appendChild(currentAssistantEl);
					}
					currentAssistantEl.innerHTML = renderMarkdown(text);
					// Promote to current (parks the previous step) once real text exists.
					makeCurrent(currentAssistantEl);
				}
			}

			if (assistantMessageEvent.type === "toolcall_delta") {
				handleStreamingEdit(event.message);
			}
			break;
		}

		case "message_end": {
			if (event.message.role === "assistant" && currentAssistantEl) {
				const text = getText(event.message);
				if (text && text.trim()) {
					currentAssistantEl.innerHTML = renderMarkdown(text);
					makeCurrent(currentAssistantEl);
				} else {
					// Empty (tool-call-only) bubble: drop it before it ever becomes current.
					currentAssistantEl.remove();
				}
				currentAssistantEl = null;
				scrollToBottom();
			}
			break;
		}

		case "tool_execution_start": {
			hideThinking();
			const desc = getExecutionDescription(event.args);
			ensureToolCallEl(event.toolCallId, event.toolName, desc);
			break;
		}

		case "tool_execution_end": {
			const el = toolCallEls.get(event.toolCallId);
			if (el) {
				markToolCallDone(el);
				toolCallEls.delete(event.toolCallId);
			}
			scrollToBottom();
			break;
		}
	}
}

function getText(message: unknown): string {
	if (typeof message !== "object" || message === null) return "";
	const msg = message as { content?: unknown };
	if (!Array.isArray(msg.content)) return "";
	for (const part of msg.content) {
		if (typeof part === "object" && part !== null && (part as { type?: string }).type === "text") {
			return (part as { text?: string }).text ?? "";
		}
	}
	return "";
}

function getExecutionDescription(args: unknown): string {
	if (args && typeof args === "object" && "description" in args) {
		return String((args as { description: unknown }).description ?? "");
	}
	return "";
}

function handleStreamingEdit(message: unknown): void {
	const edit = extractStreamingEdit(message);
	if (!edit) return;

	ensureToolCallEl(edit.id, "edit", edit.description);

	if (edit.oldText === "" && edit.newText) {
		renderPartial(getFile() + edit.newText);
	}
}

function extractStreamingEdit(message: unknown): {
	id: string;
	description: string;
	oldText: string;
	newText: string;
} | null {
	if (typeof message !== "object" || message === null) return null;
	const msg = message as { content?: unknown };
	if (!Array.isArray(msg.content)) return null;

	for (const part of msg.content) {
		if (typeof part !== "object" || part === null) continue;
		const p = part as { type?: string; name?: string; id?: string; arguments?: unknown };
		if (p.type !== "toolCall" || p.name !== "edit" || !p.id) continue;

		// Arguments may arrive as a parsed object OR as a raw partial JSON string
		// depending on the provider/streaming stage. Handle both so the preview
		// updates live regardless.
		if (p.arguments && typeof p.arguments === "object") {
			const args = p.arguments as { description?: unknown; oldText?: unknown; newText?: unknown };
			return {
				id: p.id,
				description: typeof args.description === "string" ? args.description : "",
				oldText: typeof args.oldText === "string" ? args.oldText : "",
				newText: typeof args.newText === "string" ? args.newText : "",
			};
		}

		if (typeof p.arguments === "string") {
			return {
				id: p.id,
				description: extractPartialStringField(p.arguments, "description"),
				oldText: extractPartialStringField(p.arguments, "oldText"),
				newText: extractPartialStringField(p.arguments, "newText"),
			};
		}
	}
	return null;
}

/**
 * Pull a string field value out of a (possibly truncated) JSON blob.
 * Tolerates unterminated strings so we can read `newText` mid-stream.
 */
function extractPartialStringField(rawArgs: string, field: string): string {
	const marker = `"${field}"`;
	const idx = rawArgs.indexOf(marker);
	if (idx === -1) return "";

	let i = idx + marker.length;
	while (i < rawArgs.length && /[\s:]/.test(rawArgs[i]!)) i++;
	if (rawArgs[i] !== '"') return "";
	i++;

	let out = "";
	while (i < rawArgs.length) {
		const ch = rawArgs[i]!;
		if (ch === "\\" && i + 1 < rawArgs.length) {
			const next = rawArgs[i + 1]!;
			const escapes: Record<string, string> = {
				n: "\n", t: "\t", r: "\r", "\\": "\\", '"': '"', "/": "/",
			};
			out += escapes[next] ?? next;
			i += 2;
			continue;
		}
		if (ch === "\\") break;
		if (ch === '"') break;
		out += ch;
		i++;
	}
	return out.replace(/\\+$/, "");
}
/**
 * App entry point.
 *
 * Wires together: settings → preview → agent → chat UI.
 * Everything runs client-side in the browser — no backend.
 */

import "./style.css";

import { registerProviders, createBrowserAgent } from "./agent";
import { initPreview } from "./preview";
import { initSettings, openSettingsModal, getSettings } from "./settings";
import { initChatUI } from "./chat-ui";

function main(): void {
	registerProviders();
	initSettings();
	initPreview();

	if (!getSettings().apiKey) {
		openSettingsModal();
	}

	const agent = createBrowserAgent();
	initChatUI(agent);
}

main();
/**
 * Settings management.
 *
 * Persists the model (provider/model string) and API key in localStorage.
 * Provides a modal dialog for editing settings, opened via the gear icon.
 */

export interface Settings {
	model: string;
	apiKey: string;
}

const STORAGE_KEY = "pi-browser-agent-settings";

const DEFAULT_SETTINGS: Settings = {
	model: "zai/glm-5.2",
	apiKey: "",
};

/** Read settings from localStorage, falling back to defaults. */
export function getSettings(): Settings {
	try {
		const raw = localStorage.getItem(STORAGE_KEY);
		if (!raw) return { ...DEFAULT_SETTINGS };
		return { ...DEFAULT_SETTINGS, ...JSON.parse(raw) };
	} catch {
		return { ...DEFAULT_SETTINGS };
	}
}

/** Save settings to localStorage. */
export function saveSettings(settings: Settings): void {
	localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
}

/** Parse the "provider/model" string into provider and model parts. */
export function parseModelString(modelStr: string): { provider: string; model: string } {
	const slashIdx = modelStr.indexOf("/");
	if (slashIdx === -1) {
		return { provider: "zai", model: modelStr };
	}
	return {
		provider: modelStr.slice(0, slashIdx),
		model: modelStr.slice(slashIdx + 1),
	};
}

// --- Modal UI -------------------------------------------------------------

const modal = document.getElementById("settings-modal") as HTMLDivElement;
const settingsBtn = document.getElementById("settings-btn") as HTMLButtonElement;
const cancelBtn = document.getElementById("settings-cancel") as HTMLButtonElement;
const saveBtn = document.getElementById("settings-save") as HTMLButtonElement;
const modelInput = document.getElementById("settings-model") as HTMLInputElement;
const apiKeyInput = document.getElementById("settings-apikey") as HTMLInputElement;

/** Open the settings modal, pre-filling current values. */
export function openSettingsModal(): void {
	const settings = getSettings();
	modelInput.value = settings.model;
	apiKeyInput.value = settings.apiKey;
	modal.classList.remove("hidden");
	modelInput.focus();
}

/** Close the settings modal. */
function closeModal(): void {
	modal.classList.add("hidden");
}

/** Initialize settings UI: wire buttons, pre-fill inputs. */
export function initSettings(): void {
	settingsBtn.addEventListener("click", () => openSettingsModal());
	cancelBtn.addEventListener("click", () => closeModal());

	saveBtn.addEventListener("click", () => {
		saveSettings({
			model: modelInput.value.trim() || DEFAULT_SETTINGS.model,
			apiKey: apiKeyInput.value.trim(),
		});
		closeModal();
	});

	// Close on backdrop click
	modal.addEventListener("click", (e) => {
		if (e.target === modal) closeModal();
	});

	// Close on Escape
	modal.addEventListener("keydown", (e) => {
		if (e.key === "Escape") closeModal();
	});
}
/**
 * Single in-memory file store.
 *
 * Holds one string (the entire HTML document) with callback-based change
 * notifications. This replaces a virtual filesystem — the agent works with
 * a single self-contained HTML file.
 */

type ChangeListener = (content: string) => void;

let fileContent = "";
const listeners = new Set<ChangeListener>();

/** Get the current file content. */
export function getFile(): string {
	return fileContent;
}

/** Set the file content and notify all subscribers. */
export function setFile(content: string): void {
	fileContent = content;
	for (const listener of listeners) {
		listener(fileContent);
	}
}

/** Subscribe to file changes. Returns an unsubscribe function. */
export function onChange(listener: ChangeListener): () => void {
	listeners.add(listener);
	return () => listeners.delete(listener);
}

